ARTICLES = json.loads(r'''[{"slug":"kak-pokazat-opyt-v-profile","title":"Как показать свой опыт в профессиональном профиле","description":"Пошаговая инструкция: какую профессию указать, как описать навыки и результаты работы и что проверить перед публикацией профиля.","category":"Карьера","read":"5 минут","sections":[{"title":"Начните не с возраста, а с того, какую задачу решаете","paragraphs":["Работодателю и заказчику важно быстро понять, чем вы полезны. Вместо длинной биографии начните с профессии и направления: «Бухгалтер по участкам», «Мастер смены», «Менеджер по работе с корпоративными клиентами». Если вариантов несколько, выберите основной — его легче найти через поиск.","Опишите свою специализацию двумя-тремя понятными предложениями. Избегайте общих фраз вроде «ответственный, коммуникабельный». Лучше написать, с какими задачами и инструментами вы работаете."]},{"title":"Соберите доказательства опыта","paragraphs":["Вспомните три случая, когда благодаря вашей работе что-то стало лучше: сократились ошибки, ускорились поставки, удалось обучить сотрудников, наладить учёт или удержать клиента. Укажите конкретный результат, если можете его подтвердить.","Если точных цифр нет, не придумывайте их. Назовите масштаб задач: команда, участок, ассортимент, тип клиентов или проект. Хорошее описание показывает действие и результат, а не просто перечень должностных обязанностей."],"bullets":["Работал с учётом товаров и инвентаризацией нескольких складских зон.","Обучил новых сотрудников работе с 1С и внутренними регламентами.","Наладил обработку обращений корпоративных клиентов."]},{"title":"Укажите условия, при которых готовы работать","paragraphs":["Город, формат занятости, график и желаемая оплата помогают сразу отсечь неподходящие варианты. Обновляйте их, если ваши планы изменились. Для проектной работы отдельно отметьте, какие задачи готовы брать на ограниченный срок.","Не обязательно заполнять сразу все дополнительные поля: начните с профессии, навыков, города и условий; остальное можно уточнить позднее."]},{"title":"Защитите личные контакты","paragraphs":["Не размещайте номер телефона, почту и ссылки на личные мессенджеры в открытом описании опыта. На СТАЖНО контакты скрыты по умолчанию и передаются работодателю в установленном сценарии только после вашего согласия.","После сохранения профиля используйте предпросмотр «Печать / сохранить PDF». По умолчанию контактные данные в печатной версии тоже скрыты. Перед отправкой файла внимательно проверьте его содержимое."]}]},{"slug":"kak-proverit-vakansiyu","title":"Как проверить вакансию и сохранить свои данные","description":"Практический список проверок перед откликом и собеседованием: работодатель, условия, подозрительные требования и безопасность контактов.","category":"Безопасность","read":"4 минуты","sections":[{"title":"Сначала проверьте, кто предлагает работу","paragraphs":["Название компании, сфера деятельности, адрес и корпоративные каналы связи должны складываться в понятную картину. Поищите официальный сайт организации и убедитесь, что вакансия действительно относится к ней. Если объявление размещено от имени посредника, попросите прямо назвать его роль.","Отсутствие сайта само по себе не доказывает мошенничество, особенно у небольшого бизнеса. Оценивайте сразу несколько признаков и задавайте уточняющие вопросы."]},{"title":"Уточните условия до передачи документов","paragraphs":["Узнайте, какие задачи входят в обязанности, как устроен график, где находится рабочее место, как определяется оплата и кто будет руководителем. Попросите объяснить, из чего состоит обещанный доход, особенно если в объявлении указан широкий диапазон.","Не отправляйте фото паспорта, банковские реквизиты, коды из SMS или доступы к аккаунтам на этапе обычного знакомства с вакансией. Для законного оформления документов нужен отдельный понятный процесс."]},{"title":"Сигналы, при которых стоит остановиться","paragraphs":["Насторожиться стоит, если вас торопят, просят заплатить за трудоустройство, обучение или «резервирование места», предлагают получать чужие деньги на личную карту либо скрывают название компании и обязанности.","Если общение вызывает сомнения, не переходите по неизвестным ссылкам и не устанавливайте программы удалённого доступа по просьбе незнакомого собеседника."],"bullets":["До оплаты или передачи документов попросите письменное описание условий.","Уточните ФИО и должность контактного лица в компании.","При подозрениях завершите общение и сообщите администрации площадки."]},{"title":"Используйте согласие на открытие контактов","paragraphs":["На СТАЖНО работодателю доступен профессиональный профиль, а ваши личные контакты защищены до предусмотренного согласия. Это не отменяет собственной проверки работодателя, но помогает не публиковать телефон и почту для всех посетителей.","Никакой сервис не может гарантировать отсутствие мошенников. Осторожность и проверка условий важны на каждом этапе."]}]},{"slug":"proektnaya-rabota-posle-50","title":"Подработка, проекты и наставничество: как начать","description":"Как превратить профессиональные навыки в понятное предложение для заказчика: формат, результат, объём работы и первые шаги.","category":"Новые возможности","read":"5 минут","sections":[{"title":"Выберите конкретную услугу, а не абстрактную «подработку»","paragraphs":["Многолетний опыт можно использовать не только в штатной должности. Предпринимателю может понадобиться временный бухгалтер, производству — наставник для новой смены, отделу продаж — специалист для настройки клиентской базы.","Начните с одной услуги, которую вы можете объяснить за минуту: «проведу инвентаризацию», «настрою отчётность», «обучу сотрудников правилам приёмки товара». Чем конкретнее обещанный результат, тем проще обсудить работу."]},{"title":"Определите границы работы","paragraphs":["До начала договоритесь об объёме задач, сроках, способе связи, критериях приёмки результата и вознаграждении. Если заказчик ожидает постоянной доступности, это уже другое условие — его нужно обсуждать отдельно.","Не обещайте то, что зависит от недоступной информации или решений третьих лиц. Лучше начать с небольшого понятного проекта, чем брать слишком большой и неопределённый объём."]},{"title":"Подготовьте короткую профессиональную презентацию","paragraphs":["Понадобятся несколько строк о квалификации, два примера выполненных задач и перечень инструментов, которыми владеете. Не раскрывайте конфиденциальные данные бывших работодателей. Рабочие кейсы можно описать обобщённо, без названий клиентов и коммерческих секретов.","Обновите профиль СТАЖНО, чтобы потенциальный работодатель или заказчик понимал вашу специализацию. Для личной встречи можно сохранить печатную версию резюме в PDF."]},{"title":"Измеряйте реальный результат","paragraphs":["Первым успехом может стать не большая выручка, а конкретный разговор с заинтересованным заказчиком. Записывайте, какие предложения вызывают отклик, что чаще уточняют и где остаются вопросы.","Перед началом оплачиваемой деятельности отдельно выясните применимые правила оформления договоров и налогов. Не полагайтесь на универсальные советы без учёта вашей ситуации."]}]},{"slug":"sobesedovanie-posle-50","title":"Как подготовиться к собеседованию и показать свои сильные стороны","description":"Практический план подготовки к встрече с работодателем: примеры опыта, вопросы об условиях работы и спокойный разговор о навыках.","category":"Карьера","read":"6 минут","sections":[{"title":"Подготовьте короткое представление","paragraphs":["Запишите в двух-трёх предложениях, какую работу ищете, какие задачи выполняли и в чём приносите пользу. Начните с профессиональных навыков, а не с перечисления всех должностей за много лет.","Выберите один или два конкретных примера: какую задачу нужно было решить, что сделали лично вы и какой результат получила команда. Если точных цифр нет, опишите масштаб и последовательность действий без преувеличений."]},{"title":"Сверьте требования вакансии со своим опытом","paragraphs":["Пройдитесь по описанию вакансии и напротив каждого требования запишите подходящий пример из практики. Если инструмент незнаком, назовите похожий, с которым уже работали, и объясните, как обычно осваиваете новое.","Обратите внимание на график, место работы, задачи и условия оплаты. Необязательно соглашаться с предложением сразу: собеседование нужно обеим сторонам для проверки ожиданий."]},{"title":"Задайте работодателю полезные вопросы","paragraphs":["Спросите, какие задачи будут приоритетными в первые недели, кто помогает освоиться, как оценивают результат и с кем предстоит взаимодействовать. Ответы помогут понять реальный характер работы.","Уточните, какой доход гарантирован, какая часть зависит от показателей, как устроены смены, оформление и обучение. Записывайте существенные договорённости, чтобы позже сравнить предложения."],"bullets":["Какая задача будет самой важной в первый месяц?","Как устроено обучение новым инструментам?","Из чего складывается оплата и как оценивается результат?"]},{"title":"Завершите встречу следующим шагом","paragraphs":["В конце уточните, когда можно ожидать ответ и каким способом продолжится общение. Если хотите дополнить разговор, подготовьте короткое сообщение с одним-двумя примерами опыта без личных документов.","Не отправляйте паспортные данные, коды подтверждения и доступы к аккаунтам в ответ на неожиданную просьбу. Для оформления трудовых отношений используются отдельные согласованные процедуры."]}]},{"slug":"cifrovye-navyki-dlya-raboty","title":"Цифровые навыки для работы: с чего начать без перегрузки","description":"Простой маршрут освоения рабочих онлайн-инструментов: почта, документы, видеовстречи и безопасная работа с файлами.","category":"Навыки","read":"5 минут","sections":[{"title":"Выберите одну рабочую задачу","paragraphs":["Не нужно учить все программы сразу. Выберите действие, которое действительно требуется в вакансии: отправить письмо, открыть таблицу, найти файл или подключиться к видеовстрече.","Попробуйте выполнить его на вымышленных данных. Затем повторите без подсказки и коротко запишите порядок действий. Несколько самостоятельных повторений полезнее большого списка просмотренных уроков."]},{"title":"Освойте базовые операции","paragraphs":["Начните с электронной почты: тема письма, короткий текст, вложение и проверка адресата. Следующим шагом откройте документ, внесите правку и сохраните отдельную копию.","В таблице потренируйтесь сортировать строки, пользоваться поиском и проверять значения в ячейках. Понимание этих операций полезно для многих офисных, торговых и складских задач."],"bullets":["Письмо: тема, адресат, вложение","Документ: открыть, изменить, сохранить копию","Таблица: поиск, сортировка, проверка данных","Видеовстреча: звук, камера, ссылка на подключение"]},{"title":"Отделяйте обучение от личных данных","paragraphs":["Для тренировочных файлов используйте вымышленные имена и цифры. Не загружайте базы клиентов, документы работодателя или личные сведения в неизвестные сервисы без разрешения.","Устанавливайте приложения из официальных источников, проверяйте адрес сайта перед вводом пароля и не сообщайте одноразовые коды тем, кто обращается к вам неожиданно."]},{"title":"Покажите новый навык в профиле","paragraphs":["Если научились выполнять конкретное действие, укажите именно его: «оформляю документы в текстовом редакторе», «работаю с базовыми таблицами», «участвую в видеовстречах». Не обязательно заявлять уровень эксперта.","Выберите следующую полезную задачу и двигайтесь от простого к сложному. Подтверждённое практикой умение помогает разговаривать с работодателем предметно."]}]},{"slug":"rabotodatelyu-ocenit-opyt","title":"Работодателю: как оценивать профессиональный опыт по делу","description":"Краткая методика оценки кандидатов через рабочие задачи, навыки и условия, без выводов по возрасту и стереотипам.","category":"Работодателям","read":"6 минут","sections":[{"title":"Начните с результата, который нужен бизнесу","paragraphs":["Опишите, какую задачу сотрудник должен решать самостоятельно и какой результат ожидается в первые месяцы. Это полезнее, чем длинный перечень общих качеств.","Разделите требования на обязательные и те, которым можно обучить на месте. Укажите реальные условия: график, город, оплату и необходимые инструменты."]},{"title":"Проверяйте опыт одинаковыми вопросами","paragraphs":["Для всех кандидатов подготовьте сопоставимый набор вопросов о рабочих ситуациях: что было задачей, что сделал человек, какие возникли сложности и как проверялся результат.","Не пытайтесь оценивать способность учиться, выносливость или мотивацию по возрасту. Оценивайте конкретные ответы, выполненные задания и требования должности."],"bullets":["Опишите пример задачи, которую выполняли самостоятельно.","Какие инструменты применяли и почему?","Как проверяли качество результата?","Что будете делать, если возникнет незнакомая задача?"]},{"title":"Дайте реалистичное пробное задание","paragraphs":["Если это необходимо, подготовьте короткую задачу, близкую к реальной работе. Объясните критерии оценки и не требуйте передачи конфиденциальных документов бывших работодателей.","Фиксируйте результаты по одинаковым критериям: точность, последовательность действий, коммуникация, понимание рисков. Это облегчает обоснованное сравнение кандидатов."]},{"title":"Выстройте уважительное знакомство","paragraphs":["На СТАЖНО профессиональные сведения рассматриваются без автоматической передачи личных контактов. Запрашивайте знакомство по предусмотренному механизму, а после согласия обсуждайте конкретные условия напрямую.","После принятия решения сообщите кандидату результат и следующий шаг. Понятная обратная связь улучшает опыт обеих сторон и снижает количество незавершённых откликов."]}]},{"slug":"perehod-v-novuyu-professiyu","title":"Как перейти в новую профессию, опираясь на прежний опыт","description":"Практический маршрут смены направления: переносимые навыки, пробные задачи, обучение и первые переговоры с работодателем.","category":"Карьера","read":"7 минут","sections":[{"title":"Начните с того, что уже умеете","paragraphs":["Смена профессии не обязательно означает старт с нуля. Выпишите задачи, которые вы уверенно решали: организовывали людей, вели учёт, работали с клиентами, обучали коллег или следили за качеством. Эти навыки можно применить в новой должности, даже если её название непривычно.","Отдельно отметьте, в каких условиях вам комфортно работать: за компьютером, в движении, в команде, с клиентами или самостоятельно. Хорошее направление должно подходить не только по интересу, но и по повседневному формату."]},{"title":"Сравните две-три реальные вакансии","paragraphs":["Найдите несколько объявлений по выбранному направлению и составьте таблицу: обязательные требования, знакомые инструменты, новые знания, условия оплаты. Требования, повторяющиеся в большинстве объявлений, полезнее изучать первыми.","Не оценивайте собственные возможности по одному списку требований. Если большая часть задач знакома, но не хватает одного инструмента, это может быть разумной целью для короткого обучения."]},{"title":"Проверьте направление небольшим заданием","paragraphs":["Перед оплатой большого курса попробуйте выполнить типовую задачу на вымышленных данных. Для административной работы это может быть таблица учёта, для клиентского сервиса — ответ на обращение, для наставничества — короткий учебный план.","Если задача интересна и понятна, постепенно усложняйте её. Если нет, лучше выяснить это заранее, чем продолжать дорогую программу только из-за первоначального решения."],"bullets":["Выберите одну типовую рабочую задачу.","Определите, чего именно пока не хватает.","Потренируйтесь и сохраните результат.","Опишите получившийся навык в профиле."]},{"title":"Говорите с работодателем о пользе, а не о смене возраста","paragraphs":["В резюме и на собеседовании объясните, какой прошлый опыт поможет решить новые задачи. Например: опыт координации склада пригодится в логистике, а работа с заказчиками — в сопровождении клиентов.","Уточняйте наличие стажировки, наставника и конкретные ожидания на испытательный срок. Не обещайте знания, которыми ещё не владеете, — готовность учиться лучше подтверждать уже выполненными примерами."]}]},{"slug":"kak-obsuzhdat-zarplatu","title":"Как обсуждать зарплату и условия работы без лишнего напряжения","description":"Что уточнить до согласия на предложение: фиксированная оплата, премии, график, оформление и пересмотр условий.","category":"Карьера","read":"6 минут","sections":[{"title":"Определите важные для себя условия","paragraphs":["Подумайте о минимальном приемлемом доходе, графике, дороге до рабочего места и регулярности выплат. Разделите условия на обязательные и желательные, чтобы не принимать решение только по одной красивой цифре.","Сравнивайте предложения на одинаковой основе: сумма до или после налогов, количество рабочих часов, наличие ночных смен, компенсаций и дополнительных обязанностей."]},{"title":"Разберите доход на составляющие","paragraphs":["Если указан диапазон оплаты, попросите работодателя объяснить, какая часть гарантирована, а какая зависит от показателей. Уточните, как рассчитывают премию, кто её утверждает и как часто она выплачивается.","Обсуждая условия, полезно привести конкретные результаты вашей работы, а не сравнивать себя с другими кандидатами. Вежливый уточняющий вопрос помогает выявить несовпадения ожиданий заранее."]},{"title":"Уточните режим и оформление","paragraphs":["Спросите, как оформляются отношения, когда начинаются выплаты, оплачиваются ли обучение и переработки, какое оборудование предоставляется. Если предлагается проектная работа, особенно важны результат, срок, порядок приёмки и оплата.","Не соглашайтесь отправлять деньги для получения работы, оплачивать «доступ к вакансии» или передавать коды от банковских сервисов. При настораживающих условиях завершите общение и проверьте сведения о компании."]},{"title":"Зафиксируйте следующий шаг","paragraphs":["В завершение разговора кратко повторите согласованные условия: должность, график, состав дохода и дату обратной связи. При необходимости попросите письменное предложение, чтобы внимательно его сравнить с другими вариантами.","Если после разговора появились новые условия, задайте уточняющий вопрос до принятия решения. Спокойный и предметный диалог показывает профессиональный подход с обеих сторон."]}]},{"slug":"nastavnichestvo-peredacha-opyta","title":"Наставничество: как передавать опыт и находить партнёров","description":"Как предложить практическую помощь коллегам, сформулировать цель наставничества и договориться о понятном результате.","category":"Сообщество","read":"6 минут","sections":[{"title":"Сформулируйте, чему можете научить","paragraphs":["Наставничество начинается не с громкого звания эксперта, а с конкретной задачи. Например: обучение приёмке товаров, ведению клиентских переговоров, технике безопасности или организации небольшой команды.","Назовите три-четыре темы, по которым можете показать практический пример. Не публикуйте сведения о бывших клиентах или внутренних процессах организаций без разрешения."]},{"title":"Согласуйте цель и формат","paragraphs":["Уточните, какая помощь нужна человеку: разовая консультация, разбор задачи, серия встреч или совместная работа над учебным примером. Продолжительность и формат лучше согласовать до начала общения.","Для первой встречи достаточно одной цели и короткого плана. Например: разобрать сложный рабочий случай, предложить два подхода и договориться, что участник попробует самостоятельно."]},{"title":"Проверяйте результат действием","paragraphs":["После встречи предложите человеку пересказать порядок действий или выполнить небольшое задание на безопасных данных. Это лучше показывает понимание, чем формальное согласие со всеми советами.","Не обещайте гарантированного трудоустройства, заработка или профессиональной квалификации после нескольких встреч. Чётко обозначайте границы помощи и необходимость специального обучения там, где это требуется."]},{"title":"Находите коллег через СТАЖНО","paragraphs":["В профессиональном сообществе можно отдельно рассказать о навыках и интересе к наставничеству, не публикуя личный номер и почту. Знакомство начинается с запроса, а переписка — после принятия.","Если договорились о совместном проекте, зафиксируйте задачи, сроки и условия отдельно. Поддержка коллег полезна именно тогда, когда каждый понимает свои ожидания и ответственность."]}]},{"slug":"udalyonnaya-rabota-bez-riskov","title":"Удалённая работа: как оценить предложение и подготовить рабочее место","description":"Проверка задач, графика, оборудования, оплаты и безопасности при поиске удалённой или гибридной работы.","category":"Безопасность","read":"6 минут","sections":[{"title":"Проверьте, действительно ли формат удалённый","paragraphs":["Уточните, сколько дней нужно присутствовать в офисе, в каком часовом поясе работает команда и когда вы должны быть доступны. Слово «гибридный» у разных работодателей означает разное.","Попросите пример обычного рабочего дня, перечень основных программ и описание того, как ставят задачи и оценивают результат. Так будет проще понять нагрузку и требования к навыкам."]},{"title":"Обсудите оборудование и связь","paragraphs":["Выясните, кто предоставляет компьютер, доступы к рабочим системам и техническую поддержку. Не устанавливайте неизвестные программы удалённого управления на личное устройство по неожиданному требованию.","Если планируете использовать свой компьютер, заранее проверьте стабильность интернета, возможность спокойных разговоров и обновления системы. Для домашних видеовстреч полезны наушники и отдельное место без посторонних документов в кадре."]},{"title":"Распознавайте подозрительные предложения","paragraphs":["Повод насторожиться — просьба заплатить за трудоустройство, принять деньги третьих лиц на личную карту, оформить платную подписку ради собеседования или сообщить одноразовый код. Не пересылайте документы до понятного этапа оформления.","Проверьте работодателя по открытым источникам, изучите обязанности и условия оплаты. Убедитесь, что приглашение и переписка действительно относятся к названной компании."]},{"title":"Организуйте первые рабочие недели","paragraphs":["Договоритесь, когда будут короткие встречи с руководителем, где находятся инструкции и к кому обращаться при вопросах. Ведите список задач, уточнений и результатов, чтобы не терять договорённости в сообщениях.","Если при выполнении удалённой работы обрабатываются данные клиентов, используйте только разрешённые компанией инструменты и не переносите файлы на личные облачные сервисы без согласования."]}]}]''')
BY_SLUG = {entry["slug"]: entry for entry in ARTICLES}
PUBLISHED = "2026-11-19"
ORIGIN = "https://stazhno.ru"


def _e(value: str) -> str:
    return escape(str(value), quote=True)


def _layout(title: str, description: str, path: str, body: str) -> str:
    canonical = ORIGIN + path
    return (
        "<!doctype html>\n<html lang=\"ru\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
        f"<title>{_e(title)} — СТАЖНО.РУ</title>"
        f"<meta name=\"description\" content=\"{_e(description)}\">"
        f"<link rel=\"canonical\" href=\"{_e(canonical)}\">"
        "<meta name=\"theme-color\" content=\"#0B2D26\">"
        "<link rel=\"icon\" href=\"/static/favicon.svg\" type=\"image/svg+xml\">"
        "<meta property=\"og:site_name\" content=\"СТАЖНО.РУ\">"
        f"<meta property=\"og:title\" content=\"{_e(title)}\">"
        f"<meta property=\"og:description\" content=\"{_e(description)}\">"
        f"<meta property=\"og:url\" content=\"{_e(canonical)}\">"
        "<link rel=\"stylesheet\" href=\"/static/journal.css?v=4\">"
        "<script src=\"/static/journal.js?v=4\" defer></script>"
        "</head><body class=\"jr-page\">"
        "<a class=\"jr-skip\" href=\"#jr-content\">К основному содержанию</a>"
        "<header class=\"jr-header\"><div class=\"jr-wrap jr-top\">"
        "<a class=\"jr-brand\" href=\"/\" aria-label=\"СТАЖНО.РУ — на главную\">"
        "<img src=\"/static/brand-symbol.svg\" alt=\"\" width=\"36\" height=\"36\">"
        "стажно<span>.</span>ру</a>"
        "<nav class=\"jr-nav\" aria-label=\"Основное меню\">"
        "<a href=\"/journal\">Журнал</a><a href=\"/community\">Сообщество</a><a href=\"/employers\">Работодатели</a><a href=\"/#jobs\">Вакансии</a>"
        "<a href=\"/#candidate-path\">Соискателям</a></nav>"
        "<button class=\"jr-text-toggle\" id=\"reading-mode-toggle\" aria-pressed=\"false\" "
        "type=\"button\" aria-label=\"Включить крупный текст\">Аа <span>Крупный текст</span></button>"
        "</div></header>"
        f"<main id=\"jr-content\" class=\"jr-wrap\">{body}</main>"
        "<footer class=\"jr-footer\"><div class=\"jr-wrap jr-footer-row\">"
        "<span>СТАЖНО.РУ — ваш опыт работает на вас</span>"
        "<a href=\"/\">На главную</a></div>"
        "<p class=\"jr-analytics-note jr-wrap\">Для оценки полезности материалов мы считаем только "
        "суточные суммы просмотров и переходов — без аналитических cookie и хранения "
        "данных о конкретных посетителях.</p></footer>"
        "</body></html>"
    )


def _article_card(article: dict) -> str:
    return (
        f'<a class="jr-card" data-jr-category="{_e(article["category"])}" href="/journal/{_e(article["slug"])}">'
        f'<span class="jr-tag">{_e(article["category"])}</span>'
        f'<h2>{_e(article["title"])}</h2>'
        f'<p>{_e(article["description"])}</p>'
        f'<span class="jr-card-link">Читать · {_e(article["read"])} →</span></a>'
    )


def _catalog(request: Request) -> list[dict]:
    from .journal_cms import public_articles
    with database(request.app.state.db_path) as db:
        return public_articles(db)


def journal_index(articles: list[dict] | None = None) -> HTMLResponse:
    if articles is None:
        articles = ARTICLES
    cards = "".join(_article_card(item) for item in articles)
    categories = list(dict.fromkeys(article["category"] for article in articles))
    buttons = '<button type="button" data-jr-category-filter="all" aria-pressed="true">Все темы</button>' + "".join(
        f'<button type="button" data-jr-category-filter="{_e(category)}" aria-pressed="false">{_e(category)}</button>'
        for category in categories
    )
    body = (
        '<div class="jr-breadcrumb"><a href="/">Главная</a><span aria-hidden="true">/</span>Журнал</div>'
        '<section class="jr-hero"><span class="jr-kicker">ЖУРНАЛ СТАЖНО</span>'
        '<h1>Опыт открывает новые возможности</h1>'
        '<p>Практические материалы о работе, профессиональном опыте и навыках.'
        ' Выбирайте тему и переходите к полезному действию.</p></section>'
        '<section class="jr-list" aria-label="Статьи"><h2 class="jr-list-title">Начните с полезного</h2>'
        '<div class="jr-discovery" role="search" aria-label="Поиск материалов журнала">'
        '<label for="jr-article-search">Поиск по статьям</label>'
        '<input type="search" id="jr-article-search" maxlength="100" autocomplete="off"'
        ' placeholder="Например, собеседование или навыки">'
        f'<div class="jr-category-filters" role="group" aria-label="Темы материалов">{buttons}</div>'
        f'<p class="jr-results-count" id="jr-results-count" role="status" aria-live="polite">Материалов: {len(articles)}</p>'
        '</div>'
        f'<div class="jr-grid" id="jr-article-grid">{cards}</div>'
        '<div id="jr-no-results" class="jr-no-results" hidden><strong>По вашему запросу материалов нет</strong>'
        '<p>Попробуйте другую тему или уберите слова из поиска.</p>'
        '<button type="button" id="jr-reset-search">Показать все материалы</button></div>'
        '</section>'
        '<aside class="jr-path-promo" aria-labelledby="jr-path-promo-heading">'
        '<span class="jr-kicker">НЕ ЗНАЕТЕ, С ЧЕГО НАЧАТЬ?</span>'
        '<h2 id="jr-path-promo-heading">Выберите цель — материалы уже собраны по шагам</h2>'
        '<p>Поиск работы, новые навыки или обмен опытом. Начните без регистрации.</p>'
        '<a class="jr-primary" href="/journal/paths">Посмотреть маршруты →</a></aside>'
        '<aside class="jr-bottom"><h2>Готовы использовать свой опыт?</h2>'
        '<p>Посмотрите вакансии или начните с профессионального профиля. Контакты защищены.</p>'
        '<a class="jr-primary" href="/#jobs" data-growth-action="jobs_click">Посмотреть вакансии →</a>'
        '<a class="jr-secondary" href="/#candidate-path" data-growth-action="profile_click">Создать профиль</a>'
        '</aside>'
    )
    return HTMLResponse(_layout("Журнал: работа и новые возможности после 50",
                               "Практические статьи СТАЖНО о профессиональном опыте, работе, проектах и безопасности.",
                               "/journal", body), headers={"Cache-Control": "public, max-age=300"})


def journal_article(slug: str, articles: list[dict] | None = None) -> HTMLResponse:
    if articles is None:
        articles = ARTICLES
    article = next((item for item in articles if item["slug"] == slug), None)
    if article is None:
        raise HTTPException(status_code=404, detail="Статья не найдена")
    sections = []
    for section in article["sections"]:
        content = f'<h2>{_e(section["title"])}</h2>'
        content += "".join(f'<p>{_e(p)}</p>' for p in section["paragraphs"])
        if section.get("bullets"):
            content += '<ul>' + "".join(f'<li>{_e(b)}</li>' for b in section["bullets"]) + '</ul>'
        sections.append('<section>' + content + '</section>')
    related_items = sorted(
        (item for item in articles if item["slug"] != slug),
        key=lambda item: (item["category"] != article["category"], articles.index(item)),
    )[:2]
    related_cards = "".join(_article_card(item) for item in related_items)
    article_body = (
        '<div class="jr-breadcrumb"><a href="/">Главная</a>'
        '<span aria-hidden="true">/</span><a href="/journal">Журнал</a>'
        f'<span aria-hidden="true">/</span>{_e(article["category"])}</div>'
        '<div class="jr-article-layout"><article class="jr-article">'
        f'<header><span class="jr-kicker">{_e(article["category"])}</span>'
        f'<h1>{_e(article["title"])}</h1>'
        f'<p class="jr-lead">{_e(article["description"])}</p>'
        f'<p class="jr-meta">Редакция СТАЖНО · <time datetime="{PUBLISHED}">19 ноября 2026</time>'
        f' · {_e(article["read"])} чтения</p></header>'
        + "".join(sections) + '</article>'
        '<aside class="jr-aside"><h2>Следующий шаг</h2>'
        '<p>Профессиональный профиль помогает показать навыки и условия работы.'
        ' Контакты не публикуются автоматически.</p>'
        '<a class="jr-primary" href="/#candidate-path" data-growth-action="profile_click">Создать профиль →</a>'
        '<a class="jr-secondary" href="/#jobs" data-growth-action="jobs_click">Посмотреть вакансии</a>'
        '<a class="jr-secondary" href="/community">Найти коллег</a></aside></div>'
        '<section class="jr-related" aria-label="Другие полезные материалы">'
        '<h2>Читайте также</h2>'
        f'<div class="jr-grid">{related_cards}</div></section>'
        '<p class="jr-back"><a href="/journal/paths">Маршруты чтения</a> · '
        '<a href="/journal">← Все статьи журнала</a></p>'
    )
    return HTMLResponse(_layout(article["title"], article["description"],
                               "/journal/" + slug, article_body),
                        headers={"Cache-Control": "public, max-age=300"})



def journal_highlights(request: Request) -> dict:
    """No visitor data and no unapproved editor drafts."""
    articles = _catalog(request)
    return {"articles": [
        {"slug": item["slug"], "title": item["title"],
         "description": item["description"], "category": item["category"]}
        for item in reversed(articles[-4:])
    ]}


def journal_manifest(request: Request) -> dict:
    """Public digests for exact verification of CMS-published pages.

    Never includes unpublished content, identities or visitor information.
    HTML source is still verified independently by JS/CSS asset fingerprints.
    """
    articles = _catalog(request)
    pages = {"/journal": hashlib.sha256(journal_index(articles).body).hexdigest()}
    for article in articles:
        path = "/journal/" + article["slug"]
        pages[path] = hashlib.sha256(journal_article(article["slug"], articles).body).hexdigest()
    pages["/sitemap.xml"] = hashlib.sha256(journal_sitemap(articles).body).hexdigest()
    return {"pages": pages, "count": len(articles)}


def journal_sitemap(articles: list[dict] | None = None) -> Response:
    """Only published editorial pages when a live catalog is supplied."""
    if articles is None:
        articles = ARTICLES
    from .journal_paths import visible_paths
    paths = (
        ["/", "/employers", "/journal"]
        + ["/journal/" + article["slug"] for article in articles]
        + ["/journal/paths"]
        + ["/journal/paths/" + path["slug"] for path in visible_paths(articles)]
    )
    urls = "".join(
        "<url><loc>" + _e(ORIGIN + path) + "</loc>"
        "<lastmod>" + PUBLISHED + "</lastmod></url>"
        for path in paths
    )
    xml = '<?xml version="1.0" encoding="UTF-8"?>' + (
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + urls + "</urlset>"
    )
    return Response(content=xml, media_type="application/xml",
                    headers={"Cache-Control": "public, max-age=300"})


def journal_robots(request: Request) -> PlainTextResponse:
    """Preview and unknown hosts are not search-indexable."""
    canonical_hosts = {"stazhno.ru", "www.stazhno.ru"}
    if request.url.hostname in canonical_hosts:
        policy = (
            "User-agent: *\n"
            "Disallow: /api/\n"
            "Sitemap: https://stazhno.ru/sitemap.xml\n"
        )
    else:
        policy = "User-agent: *\nDisallow: /\n"
    return PlainTextResponse(policy, headers={"Cache-Control": "public, max-age=300"})


def install_journal_routes(app: FastAPI) -> None:
    # The pure renderers still accept a default seed catalog for deterministic
    # unit/probe rendering. Public HTTP routes use current published DB rows.
    def sitemap_http(request: Request):
        return journal_sitemap(_catalog(request))

    def index_http(request: Request):
        return journal_index(_catalog(request))

    def article_http(slug: str, request: Request):
        return journal_article(slug, _catalog(request))

    app.add_api_route("/robots.txt", journal_robots, methods=["GET"], include_in_schema=False)
    app.add_api_route("/sitemap.xml", sitemap_http, methods=["GET"], include_in_schema=False)
    app.add_api_route("/journal", index_http, methods=["GET"], include_in_schema=False)
    app.add_api_route("/api/public/journal/highlights", journal_highlights, methods=["GET"], include_in_schema=False)
    app.add_api_route("/api/public/journal/manifest", journal_manifest, methods=["GET"], include_in_schema=False)
    from .journal_paths import paths_index, path_detail

    def paths_http(request: Request):
        return paths_index(_catalog(request))

    def path_detail_http(slug: str, request: Request):
        return path_detail(slug, _catalog(request))

    app.add_api_route("/journal/paths", paths_http, methods=["GET"], include_in_schema=False)
    app.add_api_route("/journal/paths/{slug}", path_detail_http, methods=["GET"], include_in_schema=False)
    app.add_api_route("/journal/{slug}", article_http, methods=["GET"], include_in_schema=False)
    from .journal_cms import install_journal_admin_routes
    install_journal_admin_routes(app)
